169	  /// 与固件 `sanitize_pkg` 一致；超长截断，防止异常包名撑爆路径。
170	  static String sanitizePackage(String pkg, [int maxChars = packageMax]) {
171	    final out = StringBuffer();
172	    for (final r in pkg.runes) {
173	      if (out.length >= maxChars) break;
174	      final c = String.fromCharCode(r);
175	      if (RegExp(r'[A-Za-z0-9._-]').hasMatch(c)) {
176	        out.write(c);
177	      } else {
178	        out.write('_');
179	      }
180	    }
181	    return out.toString();
182	  }
