186	    const ext = '.png';
187	    final maxStem = iconNameMax - ext.length;
188	    final cap = maxStem < packageMax ? maxStem : packageMax;
189	    final stem = sanitizePackage(packageName, cap);
190	    if (stem.isEmpty) return '';
