228	/// Data 帧头 8 字节：`[cmd:1][tid:1][flags:1][status:1][seq:2 le][len:2 le]`
229	abstract class CompanionFs {
230	  static const cmdHdrLen = 2;
231	  static const dataHdrLen = 8;
