252	  /// NuttX errno → 短文案。
253	  static String errnoText(int status) {
254	    return switch (status) {
255	      2 => '不存在',
256	      5 => '存储写入失败',
257	      13 => '拒绝访问',
258	      16 => '忙',
259	      17 => '已存在',
260	      22 => '参数无效',
261	      28 => '空间不足',
262	      38 => '未实现',
263	      39 => '目录非空',
264	      95 => '不支持',
265	      _ => 'errno=$status',
266	    };
267	  }
268	
269	  static const flagLast = 1 << 0;
270	  static const flagErr = 1 << 1;
271	  static const flagAckReq = 1 << 2;
272	
273	  static const entryFile = 0;
274	  static const entryDir = 1;
