276	  /// NuttX `crc32part` 初值 0，多项式 0xedb88320（无最终异或）。
277	  static const crc32Init = 0;
278	
279	  /// 与固件 `crc32part(buf, len, crc)` 一致，用于 WRITE_CLOSE / 续传前缀。
280	  static int crc32Part(List<int> data, [int crc = crc32Init]) {
281	    var value = crc;
282	    for (final b in data) {
283	      value ^= b & 0xff;
284	      for (var i = 0; i < 8; i++) {
285	        if ((value & 1) != 0) {
286	          value = (value >>> 1) ^ 0xedb88320;
287	        } else {
288	          value = value >>> 1;
289	        }
290	      }
291	    }
292	    return value >>> 0;
293	  }
294	
295	  /// WRITE_OPEN 续传回复的 `*.part` 是否就是 [data] 的前缀。
296	  ///
297	  /// 断电后最后几页可能已经计入 size 但内容不是原文。App 若仍从 offset
298	  /// 接着写，CLOSE 会因 CRC 对不上返回 errno 5。
299	  static bool resumePrefixMatches(List<int> data, int offset, int partCrc) {
300	    if (offset <= 0) return true;
301	    if (offset > data.length) return false;
302	    return crc32Part(data.sublist(0, offset)) == (partCrc >>> 0);
303	  }
