395	/// 一帧 `0xFF16` FS Data。
396	class CompanionFsFrame {
397	  /// 解析 8 字节头 + payload。
398	  CompanionFsFrame({
399	    required this.cmd,
400	    required this.tid,
401	    required this.flags,
402	    required this.status,
403	    required this.seq,
404	    required this.payload,
405	  });
406	
407	  final int cmd;
408	  final int tid;
409	  final int flags;
410	  final int status;
411	  final int seq;
412	  final Uint8List payload;
413	
414	  bool get isLast => flags & CompanionFs.flagLast != 0;
415	  bool get isErr => flags & CompanionFs.flagErr != 0;
416	
417	  factory CompanionFsFrame.fromBytes(List<int> data) {
418	    if (data.length < CompanionFs.dataHdrLen) {
419	      throw FormatException('FS 帧短于 8 字节: ${data.length}');
420	    }
421	    final bd = ByteData.sublistView(Uint8List.fromList(data));
422	    final len = bd.getUint16(6, Endian.little);
423	    final end = CompanionFs.dataHdrLen + len;
424	    if (data.length < end) {
425	      throw FormatException('FS 帧 payload 截断: 声明 $len，实际 ${data.length - 8}');
426	    }
427	    return CompanionFsFrame(
428	      cmd: bd.getUint8(0),
429	      tid: bd.getUint8(1),
430	      flags: bd.getUint8(2),
431	      status: bd.getUint8(3),
432	      seq: bd.getUint16(4, Endian.little),
433	      payload: Uint8List.fromList(data.sublist(CompanionFs.dataHdrLen, end)),
434	    );
435	  }
436	}
