438	/// LIST / STAT 条目。
439	class CompanionFsEntry {
440	  const CompanionFsEntry({
441	    required this.type,
442	    required this.size,
443	    required this.mtime,
444	    required this.name,
445	  });
446	
447	  final int type;
448	  final int size;
449	  final int mtime;
450	  final String name;
451	
452	  bool get isDir => type == CompanionFs.entryDir;
453	
454	  static List<CompanionFsEntry> parseList(Uint8List payload) {
455	    final out = <CompanionFsEntry>[];
456	    var i = 0;
457	    final bd = ByteData.sublistView(payload);
458	    while (i + 10 <= payload.length) {
459	      final type = payload[i];
460	      final size = bd.getUint32(i + 1, Endian.little);
461	      final mtime = bd.getUint32(i + 5, Endian.little);
462	      final nlen = payload[i + 9];
463	      i += 10;
464	      if (i + nlen > payload.length) break;
465	      final name = utf8.decode(
466	        payload.sublist(i, i + nlen),
467	        allowMalformed: true,
468	      );
469	      i += nlen;
470	      out.add(CompanionFsEntry(type: type, size: size, mtime: mtime, name: name));
471	    }
472	    return out;
473	  }
474	}
