523	/// [lastCtrlOp] 与 [gnssRxCount] 是设备侧的回显字段：前者证明控制写入已被处理，
524	/// 后者证明 GNSS 下行已被接收。P0 靠这两个字段完成端到端验证。
525	class CompanionStatus {
526	  /// 直接按字段构造，一般只在测试中使用。
527	  const CompanionStatus({
528	    required this.flags,
529	    required this.batteryPct,
530	    required this.lastCtrlOp,
531	    required this.storageFreeKb,
532	    required this.uptimeSec,
533	    required this.gnssRxCount,
534	    this.classicAddrRaw = const [],
535	  });
536	
537	  /// 状态字段字节长度（不含 Classic 地址拖车）。
538	  static const length = 16;
539	
540	  /// 0x0005 起的完整线格式。
541	  static const wireLength = 22;
542	
543	  /// 电量未知时 [batteryPct] 的取值。
544	  static const batteryUnknown = 0xFF;
545	
546	  /// 状态位域，取值见 [CompanionStatusFlag]。
547	  final int flags;
548	
549	  /// 电量百分比，[batteryUnknown] 表示未知。
550	  final int batteryPct;
551	
552	  /// 设备最近处理的控制操作码回显。
553	  final int lastCtrlOp;
554	
555	  /// 传输存储剩余空间，KiB。
556	  final int storageFreeKb;
557	
558	  /// 设备运行时长，秒。App 可据此发现设备重启。
559	  final int uptimeSec;
560	
561	  /// 设备累计收到的 GNSS 下行帧数。
562	  final int gnssRxCount;
563	
564	  /// Classic BD_ADDR 原始 6 字节（LSB 在前）。空表示旧固件未带拖车。
565	  final List<int> classicAddrRaw;
566	
567	  /// 给 `BluetoothSocket` 用的 `AA:BB:CC:DD:EE:FF`。空串表示未知。
568	  String get classicAddress => CompanionFs.formatBdAddr(classicAddrRaw);
569	
570	  /// 解析 16 字节状态帧（22 字节时附带 Classic 地址）；长度不足时抛 [FormatException]。
571	  factory CompanionStatus.fromBytes(List<int> data) {
572	    if (data.length < length) {
573	      throw FormatException(
574	        'Companion 状态帧长度应为 $length，实际 ${data.length}',
575	      );
576	    }
577	
578	    final bd = ByteData.sublistView(Uint8List.fromList(data));
579	    return CompanionStatus(
580	      flags: bd.getUint16(0, Endian.little),
581	      batteryPct: bd.getUint8(2),
582	      lastCtrlOp: bd.getUint8(3),
583	      storageFreeKb: bd.getUint32(4, Endian.little),
584	      uptimeSec: bd.getUint32(8, Endian.little),
585	      gnssRxCount: bd.getUint32(12, Endian.little),
586	      classicAddrRaw: data.length >= wireLength
587	          ? List<int>.from(data.sublist(length, wireLength))
588	          : const [],
589	    );
590	  }
591	
592	  /// 是否正在录制（码表骑行会话，含暂停）。
593	  bool get isRecording => flags & CompanionStatusFlag.recording != 0;
594	
595	  /// 码表判定是否正在骑行（未暂停）。
596	  bool get isMoving => flags & CompanionStatusFlag.moving != 0;
597	
598	  /// 设备是否正在采用手机下行的定位。
599	  bool get isUsingPhoneGnss => flags & CompanionStatusFlag.gpsPhone != 0;
600	
601	  /// 是否有文件传输进行中（BLE 或 USB）。
602	  bool get isTransferBusy =>
603	      flags &
604	          (CompanionStatusFlag.fsBusy | CompanionStatusFlag.usbMtpBusy) !=
605	      0;
606	
607	  /// 电量是否已知。
608	  bool get hasBattery => batteryPct != batteryUnknown;
609	
610	  @override
611	  String toString() =>
612	      'CompanionStatus(flags=0x${flags.toRadixString(16).padLeft(4, '0')}, '
613	      'batt=$batteryPct, lastCtrlOp=0x${lastCtrlOp.toRadixString(16)}, '
614	      'freeKb=$storageFreeKb, uptime=${uptimeSec}s, gnssRx=$gnssRxCount'
615	      '${classicAddress.isEmpty ? '' : ', classic=$classicAddress'})';
616	}
617	
618	/// 0xFF1A 运行槽。与固件 `COMPANION_SLOT_*` / 2SFBL `persist.boot.running` 一致。
619	abstract class CompanionSlot {
620	  static const unknown = 0;
621	  static const fw = 1;
622	  static const main = 2;
623	  static const factory = 3;
624	}
625	
626	/// 设备信息帧（特征 `0xFF1A`）。V1 为 97 字节；V2 在末尾追加 16 字节 boot 版本。
627	class CompanionDevInfo {
628	  const CompanionDevInfo({
629	    required this.slot,
630	    required this.swVersion,
631	    required this.hwVersion,
632	    this.fwName = '',
633	    this.bootVersion = '',
634	  });
635	
636	  static const swLen = 32;
637	  static const hwLen = 16;
638	  static const nameLen = 48;
639	  static const bootLen = 16;
640	  static const lengthV1 = 1 + swLen + hwLen + nameLen;
641	  static const length = lengthV1 + bootLen;
642	
643	  final int slot;
644	  final String swVersion;
645	  final String hwVersion;
646	  final String fwName;
647	  final String bootVersion;
648	
649	  /// 界面展示用：去掉 `.bin` 后缀，协议里仍是完整文件名。
650	  static String displayFwName(String name) {
651	    const suf = '.bin';
652	    if (name.length > suf.length &&
653	        name.toLowerCase().endsWith(suf)) {
654	      return name.substring(0, name.length - suf.length);
655	    }
656	    return name;
657	  }
658	
659	  String get fwLabel => displayFwName(fwName);
660	
661	  static String _cstr(List<int> data, int off, int len) {
662	    final end = off + len;
663	    var stop = end;
664	    for (var i = off; i < end; i++) {
665	      if (data[i] == 0) {
666	        stop = i;
667	        break;
668	      }
669	    }
670	    return utf8.decode(data.sublist(off, stop), allowMalformed: true).trim();
671	  }
672	
673	  factory CompanionDevInfo.fromBytes(List<int> data) {
674	    if (data.length < lengthV1) {
675	      throw FormatException(
676	        'Companion 设备信息长度至少为 $lengthV1，实际 ${data.length}',
677	      );
678	    }
679	    return CompanionDevInfo(
680	      slot: data[0],
681	      swVersion: _cstr(data, 1, swLen),
682	      hwVersion: _cstr(data, 1 + swLen, hwLen),
683	      fwName: _cstr(data, 1 + swLen + hwLen, nameLen),
684	      bootVersion: data.length >= length
685	          ? _cstr(data, lengthV1, bootLen)
686	          : '',
687	    );
688	  }
689	
690	  String get slotName => switch (slot) {
691	        CompanionSlot.fw => 'fw',
692	        CompanionSlot.main => 'main',
693	        CompanionSlot.factory => 'factory',
694	        _ => 'unknown',
695	      };
696	
697	  @override
698	  String toString() =>
699	      'CompanionDevInfo(slot=$slotName, sw=$swVersion, hw=$hwVersion'
700	      '${fwName.isEmpty ? '' : ', file=$fwName'}'
701	      '${bootVersion.isEmpty ? '' : ', boot=$bootVersion'})';
702	}
