144	/// 本机骑行记录库（documents/rides）。
145	class RideRecordStore {
146	  factory RideRecordStore() => _instance;
147	  static final RideRecordStore _instance = RideRecordStore._();
148	  RideRecordStore._();
149	
150	  Directory? _dir;
151	  final List<RideRecord> _items = [];
152	
153	  List<RideRecord> get items => List.unmodifiable(_items);
154	
155	  Future<Directory> _ensureDir() async {
156	    if (_dir != null) return _dir!;
157	    final root = await getApplicationDocumentsDirectory();
158	    _dir = Directory(p.join(root.path, 'rides'));
159	    if (!await _dir!.exists()) {
160	      await _dir!.create(recursive: true);
161	    }
162	    return _dir!;
163	  }
164	
165	  File get _indexFile => File(p.join(_dir!.path, 'index.json'));
166	
167	  /// 从磁盘加载。
168	  Future<void> load() async {
169	    await _ensureDir();
170	    _items.clear();
171	    if (!await _indexFile.exists()) return;
172	    try {
173	      final raw = jsonDecode(await _indexFile.readAsString());
174	      if (raw is List) {
175	        for (final e in raw) {
176	          if (e is Map<String, dynamic>) {
177	            _items.add(RideRecord.fromJson(Map<String, Object?>.from(e)));
178	          }
179	        }
180	      }
181	    } catch (_) {
182	      _items.clear();
183	    }
184	    _items.sort((a, b) => b.mtime.compareTo(a.mtime));
185	  }
186	
187	  Future<void> _flush() async {
188	    await _ensureDir();
189	    await _indexFile.writeAsString(
190	      jsonEncode(_items.map((e) => e.toJson()).toList()),
191	    );
192	  }
193	
194	  RideRecord? find(String fileName) {
195	    for (final e in _items) {
196	      if (e.fileName == fileName) return e;
197	    }
198	    return null;
199	  }
