248	  Future<void> remove(String fileName) async {
249	    await removeMany({fileName});
250	  }
251	
252	  /// 批量删除本机记录，不同步删码表文件。
253	  Future<void> removeMany(Set<String> fileNames) async {
254	    if (fileNames.isEmpty) return;
255	    await _ensureDir();
256	    for (final name in fileNames) {
257	      final rec = find(name);
258	      if (rec != null) {
259	        final f = File(rec.localPath);
260	        if (await f.exists()) await f.delete();
261	      }
262	    }
263	    _items.removeWhere((e) => fileNames.contains(e.fileName));
264	    await _flush();
265	  }
