267	  /// 只改手机显示名。本地文件名仍是码表 basename，再同步不会变成两条。
268	  Future<RideRecord?> setDisplayName(String fileName, String name) async {
269	    final rec = find(fileName);
270	    if (rec == null) return null;
271	    final trimmed = name.trim();
272	    if (trimmed.isEmpty) return rec;
273	    await _ensureDir();
274	    var size = rec.size;
275	    final f = File(rec.localPath);
276	    if (await f.exists()) {
277	      final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
278	      final out = utf8.encode(GpxUtil.setName(xml, trimmed));
279	      await f.writeAsBytes(out, flush: true);
280	      size = out.length;
281	    }
282	    final updated = rec.copyWith(
283	      size: size,
284	      displayName: trimmed,
285	      userRenamed: true,
286	    );
287	    final i = _items.indexWhere((e) => e.fileName == fileName);
288	    if (i >= 0) _items[i] = updated;
289	    await _flush();
290	    return updated;
291	  }
292	
293	  /// 自动命名（同步/导入后按「时间 + 起点 → 终点」起名）。
294	  ///
295	  /// 与 [setDisplayName] 的区别：**不写 GPX 里的 `<name>`**（那是全文替换，会把途经点
296	  /// 标签一起冲掉），也**不置 userRenamed** —— 自动命名不该冒充用户手动改名，
297	  /// 否则用户改完名下次同步就被覆盖了。
298	  Future<RideRecord?> setAutoName(String fileName, String name) async {
299	    final trimmed = name.trim();
300	    if (trimmed.isEmpty) return null;
301	    final rec = find(fileName);
302	    if (rec == null || rec.userRenamed) return rec;
303	    final updated = rec.copyWith(displayName: trimmed);
304	    final i = _items.indexWhere((e) => e.fileName == fileName);
305	    if (i >= 0) _items[i] = updated;
306	    await _flush();
307	    await AppLog.i('RideRecord', '自动命名 $fileName → $trimmed');
308	    return updated;
309	  }
310	
311	  /// 给还没有时长 / 缩略轨迹的记录补 GPX 数据。
312	  Future<bool> ensureDurations() async {
313	    var changed = false;
314	    for (var i = 0; i < _items.length; i++) {
315	      final rec = _items[i];
316	      if (rec.durationSec != null && rec.preview != null) continue;
317	      var sec = rec.durationSec ?? 0;
318	      var preview = rec.preview;
319	      final f = File(rec.localPath);
320	      if (await f.exists()) {
321	        try {
322	          final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
323	          final sum = GpxUtil.parse(xml);
324	          if (rec.durationSec == null) {
325	            sec = sum.duration?.inSeconds ?? 0;
326	          }
327	          preview ??= GpxUtil.previewTrack(sum.points);
328	        } catch (_) {
329	          preview ??= const [];
330	        }
331	      } else {
332	        preview ??= const [];
333	      }
334	      _items[i] = rec.copyWith(durationSec: sec, preview: preview);
335	      changed = true;
336	    }
337	    if (changed) await _flush();
338	    return changed;
339	  }
340	}
341	
342	List<LatLng>? _previewFromJson(Object? raw) {
343	  if (raw is! List) return null;
344	  final out = <LatLng>[];
345	  for (final e in raw) {
346	    if (e is List && e.length >= 2) {
347	      final lat = (e[0] as num?)?.toDouble();
348	      final lon = (e[1] as num?)?.toDouble();
349	      if (lat != null && lon != null) out.add(LatLng(lat, lon));
350	    }
351	  }
352	  return out;
353	}
