42	  /// 判断一段字节流像不像 GPX。
43	  ///
44	  /// 用途：Android 的文件选择器**没法按扩展名过滤** —— `file_selector_android`
45	  /// 用系统 `MimeTypeMap` 把 `extensions` 翻成 MIME，而 `gpx` 没有注册项会被
46	  /// 丢掉（插件日志 `Extension not supported: gpx`），只剩 `xml` → `text/xml`，
47	  /// 于是选择器被锁死在 `text/xml`，GPX 文件全部变灰选不中。所以选择时不过滤，
48	  /// 选完之后用这个函数自己认。
49	  ///
50	  /// 只看**前 64 KiB**：GPX 根元素一定在最前面，没必要把几十 MB 全解成字符串。
51	  static bool looksLikeGpx(List<int> bytes) {
52	    if (bytes.isEmpty) return false;
53	
54	    final n = bytes.length > 65536 ? 65536 : bytes.length;
55	    // latin1 逐字节映射，不会因为多字节 UTF-8 截断而抛异常。
56	    final head = String.fromCharCodes(bytes.take(n));
57	    return _gpxOpenRe.hasMatch(head);
58	  }
59	
60	  static final _openPtRe = RegExp(
61	    r'<(?:trkpt|rtept)\b([^>]*)>([\s\S]*?)</(?:trkpt|rtept)>',
62	    caseSensitive: false,
63	  );
64	
65	  static final _latAttrRe = RegExp(
66	    r'\blat="([+-]?\d+(?:\.\d+)?)"',
67	    caseSensitive: false,
68	  );
69	
70	  static final _lonAttrRe = RegExp(
71	    r'\blon="([+-]?\d+(?:\.\d+)?)"',
72	    caseSensitive: false,
73	  );
74	
75	  static final _eleRe = RegExp(
76	    r'<ele>\s*([+-]?\d+(?:\.\d+)?)\s*</ele>',
77	    caseSensitive: false,
78	  );
79	
80	  static final _hrRe = RegExp(
81	    r'<(?:[\w.]+:)?hr>\s*(\d{1,3})\s*</(?:[\w.]+:)?hr>',
82	    caseSensitive: false,
83	  );
84	
85	  static final _extClimbRe = RegExp(
86	    r'<cumulativeClimb>\s*([+-]?\d+(?:\.\d+)?)\s*</cumulativeClimb>',
87	    caseSensitive: false,
88	  );
89	
90	  static const _hrMinBpm = 30;
91	  static const _hrMaxBpm = 220;
92	
93	  /// 解析名称、点列、以及文件内可信的起止时间。
94	  static GpxSummary parse(String xml) {
95	    var name = '';
96	    final m = _nameRe.firstMatch(xml);
97	    if (m != null) {
98	      name = m.group(1)!.trim();
99	    }
100	
101	    final raw = _extractPts(xml);
102	    final points = [for (final p in raw) p.ll];
103	    final km = distanceKm(points);
104	    final times = plausibleTimes(xml);
105	    final start = times.isEmpty ? null : times.first;
106	    final end = times.isEmpty ? null : times.last;
107	    Duration? duration;
108	    if (start != null && end != null) {
109	      final d = end.difference(start);
110	      if (d.inSeconds >= 15) duration = d;
111	    }
112	    final speeds = _speedSeries(raw);
113	    final hr = _hrSeries(raw);
114	    final elev = _elev(raw);
115	    var gain = elev.gain;
116	    final extClimb = _extClimbRe.firstMatch(xml);
117	    if (gain == null && extClimb != null) {
118	      final v = double.tryParse(extClimb.group(1)!);
119	      if (v != null && v > 0.5) gain = v;
120	    }
121	    double? avg;
122	    if (duration != null && km > 0.05) {
123	      final hours = duration.inMilliseconds / 3600000.0;
124	      if (hours > 0) avg = km / hours;
125	    }
126	    if (avg == null && speeds.points.isNotEmpty) {
127	      var s = 0.0;
128	      for (final p in speeds.points) {
129	        s += p.value;
130	      }
131	      avg = s / speeds.points.length;
132	    }
133	    var atPoint = speeds.atPoint;
134	    if (avg != null && avg > 0 && atPoint.length > 1) {
135	      var any = false;
136	      for (final v in atPoint) {
137	        if (v > 0.2) {
138	          any = true;
139	          break;
140	        }
141	      }
142	      if (!any) {
143	        atPoint = List<double>.filled(atPoint.length, avg);
144	        atPoint[0] = 0;
145	      }
146	    }
147	    return GpxSummary(
148	      name: name,
149	      points: points,
150	      distanceKm: km,
151	      startTime: start,
152	      endTime: end,
153	      duration: duration,
154	      avgSpeedKmh: avg,
155	      maxSpeedKmh: speeds.max,
156	      elevGainM: gain,
157	      elevLossM: elev.loss,
158	      minEleM: elev.min,
159	      maxEleM: elev.max,
160	      avgHrBpm: hr.avg,
161	      maxHrBpm: hr.max,
162	      hrPoints: hr.points,
163	      speedPoints: speeds.points,
164	      pointSpeedsKmh: speeds.atPoint,
165	    );
166	  }
167	
168	  static List<_GpxPt> _extractPts(String xml) {
169	    final out = <_GpxPt>[];
170	    for (final match in _openPtRe.allMatches(xml)) {
171	      final ll = _llFromAttrs(match.group(1)!);
172	      if (ll == null) continue;
173	      final inner = match.group(2)!;
174	      final eleM = _eleRe.firstMatch(inner);
175	      final timeM = _timeRe.firstMatch(inner);
176	      DateTime? t;
177	      if (timeM != null) {
178	        t = tryParseUtc(timeM.group(1)!);
179	        if (t != null && !isPlausibleTime(t)) t = null;
180	      }
181	      out.add((
182	        ll: ll,
183	        ele: eleM == null ? null : double.tryParse(eleM.group(1)!),
184	        time: t,
185	        hr: _hrFromInner(inner),
186	      ));
187	    }
188	    if (out.isNotEmpty) return out;
189	    for (final match in _ptRe.allMatches(xml)) {
190	      final lat = double.tryParse(match.group(1)!);
191	      final lon = double.tryParse(match.group(2)!);
192	      if (lat != null && lon != null) {
193	        out.add((ll: LatLng(lat, lon), ele: null, time: null, hr: null));
194	      }
195	    }
196	    if (out.isNotEmpty) return out;
197	    for (final match in _ptReSwap.allMatches(xml)) {
198	      final lon = double.tryParse(match.group(1)!);
199	      final lat = double.tryParse(match.group(2)!);
200	      if (lat != null && lon != null) {
201	        out.add((ll: LatLng(lat, lon), ele: null, time: null, hr: null));
202	      }
203	    }
204	    return out;
205	  }
206	
207	  static int? _hrFromInner(String inner) {
208	    final m = _hrRe.firstMatch(inner);
209	    if (m == null) return null;
210	    final v = int.tryParse(m.group(1)!);
211	    if (v == null || v < _hrMinBpm || v > _hrMaxBpm) return null;
212	    return v;
213	  }
214	
215	  static LatLng? _llFromAttrs(String attrs) {
216	    final lat = double.tryParse(_latAttrRe.firstMatch(attrs)?.group(1) ?? '');
217	    final lon = double.tryParse(_lonAttrRe.firstMatch(attrs)?.group(1) ?? '');
218	    if (lat == null || lon == null) return null;
219	    return LatLng(lat, lon);
220	  }
221	
222	  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
223	      _speedSeries(List<_GpxPt> pts) {
224	    var maxV = 0.0;
225	    final series = <RideSeriesPoint>[];
226	    final atPoint = List<double>.filled(pts.length, 0);
227	    var last = 0.0;
228	    for (var i = 1; i < pts.length; i++) {
229	      var v = last;
230	      final a = pts[i - 1].time;
231	      final b = pts[i].time;
232	      if (a != null && b != null) {
233	        final sec = b.difference(a).inMilliseconds / 1000.0;
234	        if (sec >= 0.8 && sec <= 60) {
235	          final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
236	          final raw = km / (sec / 3600.0);
237	          if (raw > 0 && raw < 80) {
238	            v = raw;
239	            series.add(RideSeriesPoint(time: b, value: v));
240	            if (v > maxV) maxV = v;
241	          }
242	        }
243	      }
244	      atPoint[i] = v;
245	      last = v;
246	    }
247	    return (
248	      max: maxV > 0.5 ? maxV : null,
249	      points: series,
250	      atPoint: atPoint,
251	    );
252	  }
253	
254	  /// 沿轨迹每整公里一个点。
255	  ///
256	  /// [at] 是它落在轨迹上的位置，用「点下标」表示（`4.5` = 第 4、5 点之间）。回放时
257	  /// 用它判断线画到没有 —— 缺了它就只能猜，牌子要么全出来要么全不出来。
258	  static List<({LatLng ll, int km, double at})> kmMarkers(
259	    List<LatLng> points, {
260	    double intervalKm = 1,
261	    int maxMarks = 120,
262	  }) {
263	    final out = <({LatLng ll, int km, double at})>[];
264	    if (points.length < 2 || intervalKm <= 0) return out;
265	    var acc = 0.0;
266	    var next = intervalKm;
267	    var n = 1;
268	    for (var i = 1; i < points.length; i++) {
269	      final d = _haversineKm(points[i - 1], points[i]);
270	      if (d <= 0) continue;
271	      while (acc + d >= next && n <= maxMarks) {
272	        final t = ((next - acc) / d).clamp(0.0, 1.0);
273	        final a = points[i - 1];
274	        final b = points[i];
275	        out.add((
276	          ll: LatLng(
277	            a.latitude + (b.latitude - a.latitude) * t,
278	            a.longitude + (b.longitude - a.longitude) * t,
279	          ),
280	          km: n,
281	          at: (i - 1) + t,
282	        ));
283	        n++;
284	        next += intervalKm;
285	      }
286	      acc += d;
287	    }
288	    return out;
289	  }
290	
291	  /// 每个点的累计骑行时间（秒，从 0 起）。
292	  ///
293	  /// 用相邻两点的距离除以该点速度累加，还原「这段路实际花了多久」，回放时才能
294	  /// 按运动本身的速度推进（快的地方画得快）。比按点数平均更贴近真实节奏。
295	  /// 速度缺失或异常（<=0.2 km/h）时用 [fallbackKmh] 兜底。
296	  static List<double> cumulativeRideSeconds(
297	    List<LatLng> points,
298	    List<double> speedsAtPoint, {
299	    double fallbackKmh = 18,
300	  }) {
301	    final n = points.length;
302	    final out = List<double>.filled(n, 0);
303	    if (n < 2) return out;
304	    var acc = 0.0;
305	    for (var i = 1; i < n; i++) {
306	      final d = _haversineKm(points[i - 1], points[i]);
307	      var v = i < speedsAtPoint.length ? speedsAtPoint[i] : fallbackKmh;
308	      if (!(v > 0.2)) v = fallbackKmh;
309	      acc += d / v * 3600.0;
310	      out[i] = acc;
311	    }
312	    return out;
313	  }
314	
315	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _hrSeries(
316	    List<_GpxPt> pts,
317	  ) {
318	    final series = <RideSeriesPoint>[];
319	    var sum = 0;
320	    var maxV = 0;
321	    for (final p in pts) {
322	      final hr = p.hr;
323	      if (hr == null) continue;
324	      series.add(RideSeriesPoint(time: p.time, value: hr.toDouble()));
325	      sum += hr;
326	      if (hr > maxV) maxV = hr;
327	    }
328	    if (series.isEmpty) {
329	      return (avg: null, max: null, points: const []);
330	    }
331	    return (
332	      avg: (sum / series.length).round(),
333	      max: maxV,
334	      points: series,
335	    );
336	  }
337	
338	  static ({double? gain, double? loss, double? min, double? max}) _elev(
339	    List<_GpxPt> pts,
340	  ) {
341	    double? minV;
342	    double? maxV;
343	    var gain = 0.0;
344	    var loss = 0.0;
345	    double? prev;
346	    var n = 0;
347	    for (final p in pts) {
348	      final e = p.ele;
349	      if (e == null) continue;
350	      n++;
351	      minV = minV == null ? e : math.min(minV, e);
352	      maxV = maxV == null ? e : math.max(maxV, e);
353	      if (prev != null) {
354	        final d = e - prev;
355	        if (d > 0.8) gain += d;
356	        if (d < -0.8) loss += -d;
357	      }
358	      prev = e;
359	    }
360	    if (n < 2) {
361	      return (gain: null, loss: null, min: minV, max: maxV);
362	    }
363	    return (
364	      gain: gain > 0.5 ? gain : null,
365	      loss: loss > 0.5 ? loss : null,
366	      min: minV,
367	      max: maxV,
368	    );
369	  }
