475	  /// `2026-09-07T11:16:00Z`
476	  static String formatUtc(DateTime t) {
477	    final u = t.toUtc();
478	    String two(int n) => n.toString().padLeft(2, '0');
479	    return '${u.year.toString().padLeft(4, '0')}-'
480	        '${two(u.month)}-${two(u.day)}T'
481	        '${two(u.hour)}:${two(u.minute)}:${two(u.second)}Z';
482	  }
