487	  /// 相邻点球面距离之和，千米。
488	  static double distanceKm(List<LatLng> points) {
489	    var sum = 0.0;
490	    for (var i = 1; i < points.length; i++) {
491	      sum += _haversineKm(points[i - 1], points[i]);
492	    }
493	    return sum;
494	  }
495	
496	  static double _haversineKm(LatLng a, LatLng b) {
497	    const r = 6371.0;
498	    final dLat = _rad(b.latitude - a.latitude);
499	    final dLon = _rad(b.longitude - a.longitude);
500	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
501	        math.cos(_rad(a.latitude)) *
502	            math.cos(_rad(b.latitude)) *
503	            math.sin(dLon / 2) *
504	            math.sin(dLon / 2);
505	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
506	  }
507	
508	  static double _rad(double deg) => deg * math.pi / 180;
509	
510	  /// 列表缩略图用：保留起终点，中间均匀抽点。
511	  static List<LatLng> previewTrack(List<LatLng> points, {int max = 48}) {
512	    if (points.length <= 2) return List<LatLng>.from(points);
513	    if (points.length <= max) return List<LatLng>.from(points);
514	    final last = points.length - 1;
515	    final out = <LatLng>[];
516	    for (var i = 0; i < max; i++) {
517	      final idx = ((last * i) / (max - 1)).round();
518	      if (out.isEmpty || out.last != points[idx]) {
519	        out.add(points[idx]);
520	      }
521	    }
522	    if (out.last != points.last) out.add(points.last);
523	    return out;
524	  }
