563	  /// 密轨迹：track。点上写 `<time>`，默认 1 秒一点、最后一点为 [endUtc]。
564	  static String writeTrack({
565	    required String name,
566	    required List<LatLng> points,
567	    DateTime? endUtc,
568	    Duration pointInterval = const Duration(seconds: 1),
569	  }) {
570	    final end = (endUtc ?? DateTime.now()).toUtc();
571	    final n = points.length;
572	    final start = n <= 1
573	        ? end
574	        : end.subtract(pointInterval * (n - 1));
575	    final buf = StringBuffer()
576	      ..writeln('<?xml version="1.0" encoding="UTF-8"?>')
577	      ..writeln(
578	        '<gpx version="1.1" creator="Helm One App" '
579	        'xmlns="http://www.topografix.com/GPX/1/1">',
580	      )
581	      ..writeln(
582	        '  <metadata><name>${_esc(name)}</name>'
583	        '<time>${formatUtc(start)}</time></metadata>',
584	      )
585	      ..writeln('  <trk><name>${_esc(name)}</name><trkseg>');
586	    for (var i = 0; i < n; i++) {
587	      final p = points[i];
588	      final t = start.add(pointInterval * i);
589	      buf.writeln(
590	        '    <trkpt lat="${p.latitude.toStringAsFixed(7)}" '
591	        'lon="${p.longitude.toStringAsFixed(7)}">'
592	        '<time>${formatUtc(t)}</time></trkpt>',
593	      );
594	    }
595	    buf.writeln('  </trkseg></trk></gpx>');
596	    return buf.toString();
597	  }
598	
599	  /// 码表 FS 的 mtime 不可信。文件里若没有可信 `<time>`，用手机时钟补上。
600	  /// 已有 GNSS/App 时间则原样返回，不改 ele / 扩展字段。
601	  static String ensureTimestamps(String xml, {DateTime? nowUtc}) {
602	    if (plausibleTimes(xml).isNotEmpty) {
603	      return xml;
604	    }
605	    final now = (nowUtc ?? DateTime.now()).toUtc();
606	    var n = _trkptRe.allMatches(xml).length;
607	    if (n == 0) {
608	      n = _trkptSelfRe.allMatches(xml).length;
609	    }
610	    final start = n <= 1 ? now : now.subtract(Duration(seconds: n - 1));
611	    var out = _stampTrkpts(xml, now);
612	    out = _ensureMetadataTime(out, start);
613	    return out;
614	  }
615	
616	  static String _stampTrkpts(String xml, DateTime endUtc) {
617	    final blocks = _trkptRe.allMatches(xml).toList();
618	    if (blocks.isEmpty) {
619	      return _stampSelfClosing(xml, endUtc);
620	    }
621	    final n = blocks.length;
622	    final start = n <= 1
623	        ? endUtc
624	        : endUtc.subtract(Duration(seconds: n - 1));
625	    var out = xml;
626	    for (var i = n - 1; i >= 0; i--) {
627	      final m = blocks[i];
628	      final t = formatUtc(start.add(Duration(seconds: i)));
629	      out = out.replaceRange(m.start, m.end, _stampOneTrkpt(m.group(0)!, t));
630	    }
631	    return out;
632	  }
633	
634	  static String _stampSelfClosing(String xml, DateTime endUtc) {
635	    final blocks = _trkptSelfRe.allMatches(xml).toList();
636	    if (blocks.isEmpty) return xml;
637	    final n = blocks.length;
638	    final start = n <= 1
639	        ? endUtc
640	        : endUtc.subtract(Duration(seconds: n - 1));
641	    var out = xml;
642	    for (var i = n - 1; i >= 0; i--) {
643	      final m = blocks[i];
644	      final attrs = m.group(1) ?? '';
645	      final t = formatUtc(start.add(Duration(seconds: i)));
646	      out = out.replaceRange(
647	        m.start,
648	        m.end,
649	        '<trkpt$attrs><time>$t</time></trkpt>',
650	      );
651	    }
652	    return out;
653	  }
654	
655	  static String _stampOneTrkpt(String block, String iso) {
656	    if (_timeRe.hasMatch(block)) {
657	      return block.replaceFirst(_timeRe, '<time>$iso</time>');
658	    }
659	    return block.replaceFirst(
660	      RegExp(r'</trkpt>', caseSensitive: false),
661	      '<time>$iso</time></trkpt>',
662	    );
663	  }
664	
665	  static String _ensureMetadataTime(String xml, DateTime t) {
666	    final iso = formatUtc(t);
667	    final meta = _metaOpenRe.firstMatch(xml);
668	    if (meta != null) {
669	      final closeIdx = xml.toLowerCase().indexOf('</metadata>', meta.end);
670	      if (closeIdx > meta.end) {
671	        final inner = xml.substring(meta.end, closeIdx);
672	        if (_timeRe.hasMatch(inner)) {
673	          final stamped = inner.replaceFirst(_timeRe, '<time>$iso</time>');
674	          return xml.substring(0, meta.end) + stamped + xml.substring(closeIdx);
675	        }
676	        return '${xml.substring(0, meta.end)}<time>$iso</time>${xml.substring(meta.end)}';
677	      }
678	    }
679	    final gpx = _gpxOpenRe.firstMatch(xml);
680	    if (gpx == null) return xml;
681	    return '${xml.substring(0, gpx.end)}\n'
682	        '  <metadata><time>$iso</time></metadata>'
683	        '${xml.substring(gpx.end)}';
684	  }
685	
686	  /// 改 GPX 里的 `<name>`，没有则写入 metadata。分享 / 码表列表跟这个走。
687	  static String setName(String xml, String name) {
688	    final esc = _esc(name.trim());
689	    if (esc.isEmpty) return xml;
690	    if (_nameRe.hasMatch(xml)) {
691	      return xml.replaceAll(_nameRe, '<name>$esc</name>');
692	    }
693	    final meta = _metaOpenRe.firstMatch(xml);
694	    if (meta != null) {
695	      return '${xml.substring(0, meta.end)}<name>$esc</name>${xml.substring(meta.end)}';
696	    }
697	    final gpx = _gpxOpenRe.firstMatch(xml);
698	    if (gpx == null) return xml;
699	    return '${xml.substring(0, gpx.end)}\n'
700	        '  <metadata><name>$esc</name></metadata>'
701	        '${xml.substring(gpx.end)}';
702	  }
