704	  /// 码表列表文件名上限约 31 字符（含 .gpx）。
705	  static String safeFileName(String raw, {int maxChars = 31}) {
706	    var stem = raw.trim();
707	    if (stem.toLowerCase().endsWith('.gpx')) {
708	      stem = stem.substring(0, stem.length - 4);
709	    }
710	    final buf = StringBuffer();
711	    for (final r in stem.runes) {
712	      final c = String.fromCharCode(r);
713	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
714	        buf.write(c);
715	      } else if (c == ' ') {
716	        buf.write('_');
717	      }
718	    }
719	    var out = buf.toString();
720	    if (out.isEmpty) {
721	      out = 'route';
722	    }
723	    const ext = '.gpx';
724	    final cap = maxChars - ext.length;
725	    if (out.length > cap) {
726	      out = out.substring(0, cap);
727	    }
728	    return '$out$ext';
729	  }
730	
731	  /// 坐标点记录文件名（`.tsv`）。[maxChars] 按 UTF-8 字节计，给码表 `dirent` 留余量。
732	  static String safeTsvFileName(String raw, {int maxChars = 40}) {
733	    var stem = raw.trim();
734	    if (stem.toLowerCase().endsWith('.tsv')) {
735	      stem = stem.substring(0, stem.length - 4);
736	    }
737	    final buf = StringBuffer();
738	    for (final r in stem.runes) {
739	      final c = String.fromCharCode(r);
740	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
741	        buf.write(c);
742	      } else if (c == ' ') {
743	        buf.write('_');
744	      }
745	    }
746	    var out = buf.toString();
747	    if (out.isEmpty) {
748	      out = 'route';
749	    }
750	    const ext = '.tsv';
751	    final cap = maxChars - ext.length;
752	    out = WaypointTsv.capUtf8(out, cap > 1 ? cap : 1);
753	    return '$out$ext';
754	  }
