7	/// 折线 / 面积图，虚线标均值。
8	class RideSeriesChart extends StatelessWidget {
9	  const RideSeriesChart({
10	    super.key,
11	    required this.values,
12	    required this.color,
13	    this.fill = false,
14	    this.avg,
15	  });
16	
17	  final List<double> values;
18	  final Color color;
19	  final bool fill;
20	  final double? avg;
21	
22	  @override
23	  Widget build(BuildContext context) {
24	    return CustomPaint(
25	      painter: _SeriesPainter(
26	        values: downsample(values, 180),
27	        color: color,
28	        fill: fill,
29	        avg: avg,
30	      ),
31	      child: const SizedBox.expand(),
32	    );
33	  }
