35	  static List<double> downsample(List<double> src, int maxN) {
36	    if (src.length <= maxN) return src;
37	    final out = <double>[];
38	    for (var i = 0; i < maxN; i++) {
39	      final idx = (i * (src.length - 1) / (maxN - 1)).round();
40	      out.add(src[idx]);
41	    }
42	    return out;
43	  }
44	}
45	
46	class _SeriesPainter extends CustomPainter {
47	  _SeriesPainter({
48	    required this.values,
49	    required this.color,
50	    required this.fill,
51	    required this.avg,
52	  });
53	
54	  final List<double> values;
55	  final Color color;
56	  final bool fill;
57	  final double? avg;
58	
59	  @override
60	  void paint(Canvas canvas, Size size) {
61	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
62	    const pad = EdgeInsets.fromLTRB(4, 10, 4, 6);
63	    final w = size.width - pad.left - pad.right;
64	    final h = size.height - pad.top - pad.bottom;
65	    if (w <= 0 || h <= 0) return;
66	
67	    var minV = values.reduce(math.min);
68	    var maxV = values.reduce(math.max);
69	    if (avg != null) {
70	      minV = math.min(minV, avg!);
71	      maxV = math.max(maxV, avg!);
72	    }
73	    if (maxV - minV < 0.2) {
74	      minV -= 1;
75	      maxV += 1;
76	    }
77	    final span = maxV - minV;
78	
79	    Offset pt(int i, double v) {
80	      final x = pad.left +
81	          (values.length == 1 ? w / 2 : w * i / (values.length - 1));
82	      final y = pad.top + h * (1 - (v - minV) / span);
83	      return Offset(x, y);
84	    }
85	
86	    final line = Path()..moveTo(pt(0, values[0]).dx, pt(0, values[0]).dy);
87	    for (var i = 1; i < values.length; i++) {
88	      line.lineTo(pt(i, values[i]).dx, pt(i, values[i]).dy);
89	    }
90	
91	    if (fill) {
92	      final area = Path.from(line)
93	        ..lineTo(pt(values.length - 1, values.last).dx, pad.top + h)
94	        ..lineTo(pad.left, pad.top + h)
95	        ..close();
96	      canvas.drawPath(
97	        area,
98	        Paint()
99	          ..shader = LinearGradient(
100	            begin: Alignment.topCenter,
101	            end: Alignment.bottomCenter,
102	            colors: [
103	              color.withValues(alpha: 0.42),
104	              color.withValues(alpha: 0.02),
105	            ],
106	          ).createShader(Offset.zero & size),
107	      );
108	    }
109	
110	    canvas.drawPath(
111	      line,
112	      Paint()
113	        ..color = color
114	        ..style = PaintingStyle.stroke
115	        ..strokeWidth = 2.2
116	        ..strokeJoin = StrokeJoin.round
117	        ..strokeCap = StrokeCap.round,
118	    );
119	
120	    final a = avg;
121	    if (a != null) {
122	      final y = pt(0, a).dy;
123	      _dash(
124	        canvas,
125	        Offset(pad.left, y),
126	        Offset(pad.left + w, y),
127	        Paint()
128	          ..color = color.withValues(alpha: 0.7)
129	          ..strokeWidth = 1.2,
130	      );
131	    }
132	  }
133	
134	  static void _dash(Canvas canvas, Offset a, Offset b, Paint paint) {
135	    const dash = 5.0;
136	    const gap = 4.0;
137	    final len = (b - a).distance;
138	    if (len < 1) return;
139	    final dir = (b - a) / len;
140	    var t = 0.0;
141	    while (t < len) {
142	      final end = math.min(t + dash, len);
143	      canvas.drawLine(a + dir * t, a + dir * end, paint);
144	      t += dash + gap;
145	    }
146	  }
147	
148	  @override
149	  bool shouldRepaint(covariant _SeriesPainter old) =>
150	      old.values != values ||
151	      old.color != color ||
152	      old.fill != fill ||
153	      old.avg != avg;
154	}
