209	class _BarPainter extends CustomPainter {
210	  _BarPainter({
211	    required this.values,
212	    required this.labels,
213	    required this.color,
214	    required this.avg,
215	    required this.avgText,
216	    required this.highlight,
217	  });
218	
219	  final List<double> values;
220	  final List<String> labels;
221	  final Color color;
222	  final double? avg;
223	  final String? avgText;
224	  final int highlight;
225	
226	  static const _emptyBar = Color(0xFF3A3A3C);
227	  static const _labelColor = Color(0xFF8E8E93);
228	
229	  @override
230	  void paint(Canvas canvas, Size size) {
231	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
232	    final w = size.width;
233	    // 有标签才留那一行；迷你图（labels 全空）就贴边画，别浪费高度。
234	    final hasLabel = labels.any((l) => l.isNotEmpty);
235	    final padTop = hasLabel ? 10.0 : 3.0;
236	    final padBottom = hasLabel ? 17.0 : 3.0;
237	    final h = size.height - padTop - padBottom;
238	    if (h <= 0) return;
239	
240	    final maxV = values.fold<double>(0, math.max);
241	    final scaleMax = math.max(maxV, avg ?? 0) * 1.12;
242	    final slot = w / values.length;
243	    final barW = math.min(slot * 0.62, 18.0);
244	
245	    for (var i = 0; i < values.length; i++) {
246	      final v = values[i];
247	      final cx = slot * (i + 0.5);
248	      final frac = scaleMax <= 0 ? 0.0 : (v / scaleMax).clamp(0.0, 1.0);
249	      // 0 也留 2 px 灰底：能看出「这一天存在、只是没骑」。
250	      final barH = frac <= 0 ? 2.0 : math.max(2.0, h * frac);
251	      final isHi = i == highlight;
252	
253	      canvas.drawRRect(
254	        RRect.fromRectAndRadius(
255	          Rect.fromLTWH(cx - barW / 2, padTop + h - barH, barW, barH),
256	          Radius.circular(math.min(barW / 2, 3)),
257	        ),
258	        Paint()
259	          ..color = v <= 0
260	              ? _emptyBar
261	              : (isHi ? color : color.withValues(alpha: 0.55)),
262	      );
263	
264	      final label = i < labels.length ? labels[i] : '';
265	      if (label.isEmpty) continue;
266	      final tp = TextPainter(
267	        text: TextSpan(
268	          text: label,
269	          style: TextStyle(
270	            color: isHi ? Colors.white : _labelColor,
271	            fontSize: 10,
272	            fontWeight: isHi ? FontWeight.w700 : FontWeight.w400,
273	          ),
274	        ),
275	        textDirection: TextDirection.ltr,
276	      )..layout();
277	      tp.paint(canvas, Offset(cx - tp.width / 2, size.height - padBottom + 4));
278	    }
279	
280	    final a = avg;
281	    if (a != null && a > 0) {
282	      final y = padTop + h * (1 - (a / scaleMax).clamp(0.0, 1.0));
283	      final paint = Paint()
284	        ..color = color.withValues(alpha: 0.85)
285	        ..strokeWidth = 1.4;
286	      _SeriesPainter._dash(canvas, Offset(0, y), Offset(w, y), paint);
287	
288	      // 数值标签贴在线右端上方：只有一条线看不出它落在哪一档。
289	      final text = avgText;
290	      if (text != null && text.isNotEmpty) {
291	        final tp = TextPainter(
292	          text: TextSpan(
293	            text: text,
294	            style: TextStyle(
295	              color: color,
296	              fontSize: 9,
297	              fontWeight: FontWeight.w700,
298	            ),
299	          ),
300	          textDirection: TextDirection.ltr,
301	        )..layout();
302	        tp.paint(canvas, Offset(w - tp.width, y - tp.height - 2));
303	      }
304	    }
305	  }
306	
307	  @override
308	  bool shouldRepaint(covariant _BarPainter old) =>
309	      old.values != values ||
310	      old.labels != labels ||
311	      old.color != color ||
312	      old.avg != avg ||
313	      old.avgText != avgText ||
314	      old.highlight != highlight;
315	}
