343	class _PacePainter extends CustomPainter {
344	  _PacePainter({required this.speeds, this.range});
345	
346	  final List<double> speeds;
347	  final ({double lo, double hi})? range;
348	
349	  @override
350	  void paint(Canvas canvas, Size size) {
351	    final r = RRect.fromRectAndRadius(
352	      Offset.zero & size,
353	      const Radius.circular(5),
354	    );
355	    canvas.save();
356	    canvas.clipRRect(r);
357	    if (speeds.length < 2) {
358	      canvas.drawRRect(
359	        r,
360	        Paint()
361	          ..shader = const LinearGradient(
362	            colors: [
363	              RideTrackStyle.bandSlow,
364	              RideTrackStyle.bandMid,
365	              RideTrackStyle.bandFast,
366	            ],
367	          ).createShader(Offset.zero & size),
368	      );
369	    } else {
370	      final minV = range?.lo ?? speeds.reduce(math.min);
371	      final maxV = range?.hi ?? speeds.reduce(math.max);
372	      final w = size.width / speeds.length;
373	      for (var i = 0; i < speeds.length; i++) {
374	        // 与轨迹线共用同一个映射（[RideTrackStyle.speedBandColor]），颜色才对得上。
375	        canvas.drawRect(
376	          Rect.fromLTWH(i * w, 0, w + 0.6, size.height),
377	          Paint()..color = RideTrackStyle.speedBandColor(speeds[i], minV, maxV),
378	        );
379	      }
380	    }
381	    canvas.restore();
382	  }
383	
384	  @override
385	  bool shouldRepaint(covariant _PacePainter old) =>
386	      old.speeds != speeds || old.range != range;
387	}
