100	  Future<void> _loadPts() async {
101	    final rec = _rec;
102	    if (rec == null) return;
103	    final f = File(rec.localPath);
104	    if (!await f.exists()) return;
105	    final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
106	    final sum = GpxUtil.parse(xml);
107	    final speeds = sum.pointSpeedsKmh;
108	    // 回放时间轴：按「距离 / 速度」累加，快的地方画得快。
109	    final rideT = GpxUtil.cumulativeRideSeconds(sum.points, speeds);
110	    final total = rideT.isEmpty ? 0.0 : rideT.last;
111	    if (!mounted) return;
112	    setState(() {
113	      _sum = sum;
114	      _pts = sum.points;
115	      _disp = HelmOsmTiles.toDisplayAll(sum.points);
116	      _rideT = rideT;
117	      _rideTotal = total;
118	      _stops = RideTrackStyle.bandStops(
119	        speeds,
120	        fallbackKmh: sum.avgSpeedKmh ?? 18,
121	      );
122	    });
123	    _startPlayback();
124	  }
125	
126	  /// 进场自动回放一次。
127	  ///
128	  /// 把整段骑行时长等比压进 [_playMaxSec] 秒内播完：等比压缩保留了各段的快慢差别，
129	  /// 所以「以运动的速度绘制」这件事在压缩后依然成立。本来就比上限短的按实际时长播。
130	  void _startPlayback() {
131	    if (_disp.length < 2) return;
132	    final secs = _rideTotal > 0 ? _rideTotal : _playMaxSec;
133	    _play.duration = Duration(
134	      milliseconds: (secs.clamp(0.6, _playMaxSec) * 1000).round(),
135	    );
136	    _play.forward(from: 0);
137	  }
138	
139	  /// 当前画到的小数下标（4.5 表示在第 4、5 点之间）。
140	  double get _playCut {
141	    if (_disp.length < 2) return 0;
142	    // 没有速度信息 → 没有时间轴，按点数均匀播。
143	    if (_rideT.length != _disp.length || _rideTotal <= 0) {
144	      return _play.value * (_disp.length - 1);
145	    }
146	    final sec = _play.value * _rideTotal;
147	    // 播完就整条。二进制查找找的是「第一个 >= sec 的下标」，如果尾部有一串
148	    // 零位移点（原地停留，累计时间相同）会停在那串的第一个上，线就画不到底、
149	    // 游标也不消失。
150	    if (sec >= _rideTotal) return _disp.length - 1;
151	    var lo = 0;
152	    var hi = _rideT.length - 1;
153	    while (lo < hi) {
154	      final mid = (lo + hi) >> 1;
155	      if (_rideT[mid] < sec) {
156	        lo = mid + 1;
157	      } else {
158	        hi = mid;
159	      }
160	    }
161	    final i = lo < 1 ? 1 : lo;
162	    final t0 = _rideT[i - 1];
163	    final t1 = _rideT[i];
164	    final f = t1 - t0 <= 0 ? 1.0 : ((sec - t0) / (t1 - t0)).clamp(0.0, 1.0);
165	    return (i - 1) + f;
166	  }
