184	  void _onSheetDragUpdate(double dy, double bodyH) {
185	    final travel = bodyH * 0.5 - _peekBody;
186	    if (travel <= 8) return;
187	    if (_sheet.isAnimating) _sheet.stop();
188	    _sheet.value = (_sheet.value - dy / travel).clamp(0.0, 1.0);
189	  }
190	
191	  void _onSheetDragEnd(double velocity) {
192	    final next = velocity < -350
193	        ? 1.0
194	        : velocity > 350
195	            ? 0.0
196	            : _sheet.value >= 0.45
197	                ? 1.0
198	                : 0.0;
199	    _sheet.animateTo(next, curve: Curves.easeOutCubic);
200	  }
