202	  CameraFit? _fitOf(List<LatLng> pts, {EdgeInsets padding = _mapPad}) {
203	    if (pts.length < 2) return null;
204	    return CameraFit.bounds(
205	      bounds: LatLngBounds.fromPoints(pts),
206	      padding: padding,
207	      maxZoom: 16,
208	      minZoom: 3,
209	      forceIntegerZoomLevel: true,
210	    );
211	  }
