213	  /// 用控件真实尺寸算出第一帧相机，避免先对着起点再跳到整条轨迹。
214	  ({LatLng center, double zoom})? _cameraFor(
215	    List<LatLng> pts,
216	    Size size, {
217	    EdgeInsets padding = _mapPad,
218	  }) {
219	    final fit = _fitOf(pts, padding: padding);
220	    if (fit == null || size.width < 8 || size.height < 8) return null;
221	    try {
222	      final fitted = fit.fit(
223	        MapCamera(
224	          crs: const Epsg3857(),
225	          center: pts.first,
226	          zoom: 10,
227	          rotation: 0,
228	          nonRotatedSize: size,
229	          minZoom: 3,
230	          maxZoom: 18,
231	        ),
232	      );
233	      return (center: fitted.center, zoom: fitted.zoom);
234	    } catch (_) {
235	      return null;
236	    }
237	  }
