297	  Future<void> _shareImage() async {
298	    final rec = _rec;
299	    if (rec == null || _sharing) return;
300	    setState(() => _sharing = true);
301	    try {
302	      await WidgetsBinding.instance.endOfFrame;
303	      if (!mounted) return;
304	      if (_pts.length >= 2) {
305	        _fitTrack(_shareMap);
306	        await Future<void>.delayed(const Duration(milliseconds: 700));
307	      }
308	      if (!mounted) return;
309	      final boundary =
310	          _shotKey.currentContext?.findRenderObject() as RenderRepaintBoundary?;
311	      if (boundary == null) {
312	        throw StateError('map not ready');
313	      }
314	      final dpr = MediaQuery.devicePixelRatioOf(context).clamp(2.0, 3.0);
315	      final image = await boundary.toImage(pixelRatio: dpr);
316	      final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
317	      if (bytes == null) {
318	        throw StateError('empty png');
319	      }
320	      final dir = await getTemporaryDirectory();
321	      final stem = rec.fileName.toLowerCase().endsWith('.gpx')
322	          ? rec.fileName.substring(0, rec.fileName.length - 4)
323	          : rec.fileName;
324	      final file = File(p.join(dir.path, 'helm_$stem.png'));
325	      await file.writeAsBytes(bytes.buffer.asUint8List(), flush: true);
326	      final caption = RidePoster.shareCaption(rec, _sum);
327	      await SharePlus.instance.share(
328	        ShareParams(
329	          files: [
330	            XFile(file.path, mimeType: 'image/png', name: '${rec.title}.png'),
331	          ],
332	          text: caption,
333	        ),
334	      );
335	    } catch (e, st) {
336	      if (!mounted) return;
337	      AppTheme.fail(LocaleKeys.rideShareImage.tr, 'RideShare', e, st);
338	    } finally {
339	      if (mounted) setState(() => _sharing = false);
340	    }
341	  }
