509	  /// [playable] 为 true 时地图跟着回放进度重建（只有详情页的主地图要）。
510	  Widget _mapView(
511	    MapController controller, {
512	    EdgeInsets fitPad = _mapPad,
513	    bool playable = false,
514	  }) {
515	    if (_disp.isEmpty) {
516	      return const ColoredBox(
517	        color: Color(0xFFEDE8DF),
518	        child: Center(
519	          child: Icon(Icons.map_outlined, color: AppTheme.muted, size: 48),
520	        ),
521	      );
522	    }
523	    Widget build({required double? cut}) => LayoutBuilder(
524	      builder: (context, box) {
525	        final mapSize = Size(box.maxWidth, box.maxHeight);
526	        if (mapSize.width < 8 || mapSize.height < 8) {
527	          return const ColoredBox(color: Color(0xFFEDE8DF));
528	        }
529	        final cam = _cameraFor(_disp, mapSize, padding: fitPad);
530	        return FlutterMap(
531	          mapController: controller,
532	          options: MapOptions(
533	            initialCenter: cam?.center ?? _disp.first,
534	            initialZoom: cam?.zoom ?? 14,
535	            minZoom: 3,
536	            maxZoom: 18,
537	            interactionOptions: const InteractionOptions(
538	              flags: InteractiveFlag.all & ~InteractiveFlag.rotate,
