7	/// 与码表一致：慢绿 / 巡航青 / 快红。
8	abstract class RideTrackStyle {
9	  /// 速度色带三档色。与总览速度条（`RidePaceStrip`）共用，两边颜色才对得上。
10	  static const bandSlow = Color(0xFF3DDC84);
11	  static const bandMid = Color(0xFFFFD54A);
12	  static const bandFast = Color(0xFFFF5C33);
13	
14	  /// 码表上那条线的分档配色（按绝对速度：0–18 绿、18–32 青、32+ 红）。
15	  ///
16	  /// App 里的轨迹线和速度条改走 [speedBandColor]（按本次骑行归一化，和速度条一致），
17	  /// 这个函数保留下来只作为与码表配色对照的依据。
18	  static Color speedColor(double kph) {
19	    var v = kph;
20	    if (v < 0) v = 0;
21	    if (v < 18) {
22	      final t = v / 18;
23	      return Color.fromARGB(
24	        255,
25	        (20 + 20 * t).round(),
26	        (168 + 42 * t).round(),
27	        (72 + 28 * t).round(),
28	      );
29	    }
30	    if (v < 32) {
31	      final t = (v - 18) / 14;
32	      return Color.fromARGB(
33	        255,
34	        (40 * (1 - t)).round(),
35	        (210 - 50 * t).round(),
36	        (100 + 120 * t).round(),
37	      );
38	    }
39	    final t = ((v - 32) / 16).clamp(0.0, 1.0);
40	    return Color.fromARGB(
41	      255,
42	      (255 * t).round(),
43	      (160 * (1 - t)).round(),
44	      (220 * (1 - t) + 32 * t).round(),
45	    );
46	  }
47	
48	  /// 速度 → 色带颜色，[value] 在 [minV]..[maxV] 之间归一化（绿 → 黄 → 红）。
49	  ///
50	  /// 轨迹线和速度条都调这一个函数。以前轨迹线按绝对速度分档、速度条按本次骑行
51	  /// 归一化，同一条轨迹上两条东西的颜色是对不上的。
52	  static Color speedBandColor(double value, double minV, double maxV) {
53	    var lo = minV;
54	    var hi = maxV;
55	    if (hi - lo < 0.4) {
56	      lo -= 0.5;
57	      hi += 0.5;
58	    }
59	    final t = ((value - lo) / (hi - lo)).clamp(0.0, 1.0);
60	    return t < 0.5
61	        ? Color.lerp(bandSlow, bandMid, t * 2)!
62	        : Color.lerp(bandMid, bandFast, (t - 0.5) * 2)!;
63	  }
64	
65	  /// 速度区间，供色带归一化用。
66	  ///
67	  /// **必须用原始序列算，不能用平滑后的。** 实测某条轨迹原始是 1.6–79.1 km/h，
68	  /// 被 ±48 点的滑动平均压成 16.0–31.4；中位速度 22.8 在原始区间里是 t=0.27（绿），
69	  /// 在压缩区间里变成 t=0.44（黄橙）—— 同一条轨迹上「线」和「速度条」就差出半条色带，
70	  /// 也就是用户看到的「上下颜色没对上」。
71	  ///
72	  /// 全无有效值时返回 `null`。
73	  static ({double lo, double hi})? bandRange(List<double> speedsAtPoint) {
74	    var lo = double.infinity;
75	    var hi = double.negativeInfinity;
76	    for (final v in speedsAtPoint) {
77	      if (!(v > 0.2)) continue;
78	      if (v < lo) lo = v;
79	      if (v > hi) hi = v;
80	    }
81	    if (lo == double.infinity) return null;
82	    return (lo: lo, hi: hi);
83	  }
84	
85	  /// 把整条轨迹的速度抽成色标（给轨迹线的 `gradientColors`）。
86	  ///
87	  /// 取值方式和速度条一致：**按位置取样，不做平滑**（速度条的 `downsample` 同样是
88	  /// 取样）。120 个色标本身就是「每段距离一个」，已经足够平滑；再叠一层滑动平均
89	  /// 会把峰值削掉 —— 实测某条轨迹原始峰值 79 km/h，±2 点平滑后就只剩 49，线到不了
90	  /// 红色，而速度条那时已经是红的。
91	  ///
92	  /// 加载时算一次就够：逐帧重算是「点数 × 窗口」的量级，回放会掉帧。
93	  static List<Color> bandStops(
94	    List<double> speedsAtPoint, {
95	    double fallbackKmh = 18,
96	    int maxStops = 120,
97	    ({double lo, double hi})? range,
98	  }) {
99	    final n = speedsAtPoint.length;
100	    // 完全没有速度信息时给一条纯色：画成绿到红会被误读成「有快有慢」。
101	    if (n == 0 || !speedsAtPoint.any((v) => v > 0.2)) {
102	      return const [bandSlow, bandSlow];
103	    }
104	    final r = range ?? bandRange(speedsAtPoint)!;
105	    final stops = maxStops < 2 ? 2 : (maxStops > n ? n : maxStops);
106	    return [
107	      for (var i = 0; i < stops; i++)
108	        speedBandColor(
109	          _speedAt(speedsAtPoint, ((i / (stops - 1)) * (n - 1)).round(), fallbackKmh),
110	          r.lo,
111	          r.hi,
112	        ),
113	    ];
114	  }
115	
116	  /// 第 [i] 个点的速度；越界或缺失（<=0.2）时用 [fallback]。
117	  static double _speedAt(List<double> speeds, int i, double fallback) {
118	    if (i < 0 || i >= speeds.length) return fallback;
119	    final v = speeds[i];
120	    return v > 0.2 ? v : fallback;
121	  }
122	
123	  /// [stops] 里对应「画到小数下标 [cut]」的那一段。总数不足则原样返回。
124	  static List<Color> stopsUpTo(List<Color> stops, double cut, int totalPoints) {
125	    if (stops.length < 2 || totalPoints < 2) return stops;
126	    if (cut >= totalPoints - 1) return stops;
127	    final frac = (cut / (totalPoints - 1)).clamp(0.0, 1.0);
128	    final m = (frac * (stops.length - 1)).round().clamp(1, stops.length - 1);
129	    return stops.sublist(0, m + 1);
130	  }
131	
132	  /// 小数下标 [cut] 对应的位置（回放游标用）。
133	  static LatLng? pointAt(List<LatLng> disp, double cut) {
134	    final pts = revealPoints(disp, cut);
135	    return pts.isEmpty ? null : pts.last;
136	  }
137	
138	  /// 画到小数下标 [cut]：取整段，再在最后一段上插一个点。
139	  static List<LatLng> revealPoints(List<LatLng> disp, double cut) {
140	    if (disp.isEmpty) return const [];
141	    final i = cut.floor().clamp(0, disp.length - 1);
142	    final f = (cut - i).clamp(0.0, 1.0);
143	    final out = disp.sublist(0, i + 1);
144	    if (f > 0 && i + 1 < disp.length) {
145	      final a = disp[i];
146	      final b = disp[i + 1];
147	      out.add(
148	        LatLng(
149	          a.latitude + (b.latitude - a.latitude) * f,
150	          a.longitude + (b.longitude - a.longitude) * f,
151	        ),
152	      );
153	    }
154	    return out;
155	  }
156	
157	  /// 轨迹线。[cut] 为 `null` 画整条；给小数下标则只画到那里（逐段回放）。
158	  static List<Polyline> speedPolylines(
159	    List<LatLng> disp, {
160	    required List<Color> stops,
161	    double? cut,
162	  }) {
163	    if (disp.length < 2 || stops.isEmpty) return const [];
164	    const casing = Color(0xEEFFFFFF);
165	    final c = cut;
166	    if (c == null || c >= disp.length - 1) {
167	      return [
168	        Polyline(points: disp, strokeWidth: 9, color: casing),
169	        Polyline(
170	          points: disp,
171	          strokeWidth: 5,
172	          color: stops[stops.length ~/ 2],
173	          gradientColors: stops,
174	        ),
175	      ];
176	    }
177	    final pts = revealPoints(disp, c);
178	    if (pts.length < 2) return const [];
179	    // 色标只在整条上算一次，这里切片 —— 回放中颜色不会随进度漂移。
180	    final colors = stopsUpTo(stops, c, disp.length);
181	    return [
182	      Polyline(points: pts, strokeWidth: 9, color: casing),
183	      Polyline(
184	        points: pts,
185	        strokeWidth: 5,
186	        color: colors[colors.length ~/ 2],
187	        gradientColors: colors,
188	      ),
189	    ];
190	  }
191	
192	}
