369	/// 轨迹层。
370	///
371	/// 公里牌和起终点是**线画到哪儿才在哪儿浮现**的：回放中牌子随着线经过依次长出来，
372	/// 而不是一开始全摆在地图上。浮现进度直接由回放进度算（见 [_Emerging]），不另跑动画。
373	/// [cut] 为 `null`（分享封面等）时全部按已浮现处理。
374	List<Widget> rideTrackLayers({
375	  required List<LatLng> display,
376	  required GpxSummary? summary,
377	  required List<LatLng> wgs,
378	  required List<Color> stops,
379	  double? cut,
380	}) {
381	  if (display.length < 2) return const [];
382	  final done = cut == null || cut >= display.length - 1;
383	  final head = done ? null : RideTrackStyle.pointAt(display, cut);
384	
385	  // 浮现窗口：线越过标记之后再走这么多「点」才完全显形（约全程 3%）。
386	  final fade = ((display.length - 1) * 0.03).clamp(1.0, 40.0);
387	  double emerge(double at) => done ? 1.0 : ((cut - at) / fade).clamp(0.0, 1.0);
388	
389	  final markers = <Marker>[];
390	  for (final m in GpxUtil.kmMarkers(wgs)) {
391	    final t = emerge(m.at);
392	    if (t <= 0) continue;
393	    markers.add(
394	      Marker(
395	        point: HelmOsmTiles.toDisplay(m.ll),
396	        width: 22,
397	        height: 22,
398	        child: _Emerging(t: t, child: RideKmBadge(km: m.km)),
399	      ),
400	    );
401	  }
402	
403	  // 起点从第一帧起长出来。
404	  final startT = emerge(0);
405	  if (startT > 0) {
406	    markers.add(
407	      Marker(
408	        point: display.first,
409	        width: 26,
410	        height: 26,
411	        child: _Emerging(t: startT, child: const RideStartGrid()),
412	      ),
413	    );
414	  }
415	  // 终点：「画到」正好是回放结束那一刻，窗口往前挪一点，否则只能在结束瞬间硬弹出来。
416	  final finishT = emerge(display.length - 1 - fade);
417	  if (finishT > 0) {
418	    markers.add(
419	      Marker(
420	        point: display.last,
421	        width: 30,
422	        height: 38,
423	        alignment: Alignment.bottomCenter,
424	        child: _Emerging(t: finishT, child: const RideFinishFlag()),
425	      ),
426	    );
427	  }
428	
429	  // 游标画在最后，压在标记之上。
430	  if (head != null) {
431	    markers.add(
432	      Marker(point: head, width: 22, height: 22, child: const RidePlayHead()),
433	    );
434	  }
435	
436	  return [
437	    PolylineLayer(
438	      polylines: RideTrackStyle.speedPolylines(
439	        display,
440	        stops: stops,
441	        cut: done ? null : cut,
442	      ),
443	    ),
444	    if (markers.isNotEmpty) MarkerLayer(markers: markers),
445	  ];
446	}
