449	///
450	/// 不插一个「入场动画」：地图每帧都在重建，入场动画会反复重播。这里直接用回放进度
451	/// 算，帧帧一致，往回拖也停在正确的中间态。
452	class _Emerging extends StatelessWidget {
453	  const _Emerging({required this.t, required this.child});
454	
455	  final double t;
456	  final Widget child;
457	
458	  @override
459	  Widget build(BuildContext context) {
460	    return Opacity(
461	      opacity: t,
462	      // 从底边长出来：旗子和圆牌都是下沿先落地。
463	      child: Transform.scale(
464	        scale: 0.55 + 0.45 * t,
465	        alignment: Alignment.bottomCenter,
466	        child: child,
467	      ),
468	    );
469	  }
470	}
