Path _monotonePath(List<Offset> p) {
  final path = Path()..moveTo(p[0].dx, p[0].dy);
  if (p.length == 2) { path.lineTo(...); return path; }
  final n = p.length;
  final d = List<double>.filled(n - 1, 0);
  for (var i = 0; i < n - 1; i++) {
    final dx = p[i+1].dx - p[i].dx;
    d[i] = dx.abs() < 1e-6 ? 0 : (p[i+1].dy - p[i].dy) / dx;
  }
  final m = List<double>.filled(n, 0);
  m[0] = d[0]; m[n-1] = d[n-2];
  for (var i = 1; i < n - 1; i++) {
    if (d[i-1] * d[i] <= 0) { m[i] = 0; } else { m[i] = (d[i-1] + d[i]) / 2; }
  }
  // Fritsch–Carlson clamp
  for (var i = 0; i < n - 1; i++) {
    if (d[i] == 0) { m[i] = 0; m[i+1] = 0; continue; }
    final a = m[i] / d[i], b = m[i+1] / d[i];
    final s = a*a + b*b;
    if (s > 9) { final t = 3 / math.sqrt(s); m[i] = t*a*d[i]; m[i+1] = t*b*d[i]; }
  }
  for (var i = 0; i < n - 1; i++) {
    final dx = p[i+1].dx - p[i].dx;
    final c1 = Offset(p[i].dx + dx/3, p[i].dy + m[i]*dx/3);
    final c2 = Offset(p[i+1].dx - dx/3, p[i+1].dy - m[i+1]*dx/3);
    path.cubicTo(c1.dx, c1.dy, c2.dx, c2.dy, p[i+1].dx, p[i+1].dy);
  }
  return path;
}
```

